import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = (1 << 19) | 5;
    static int total_numbers, exponent, modulus, max_value;
    static int[] count = new int[MAX_SIZE];
    static int[] f_array = new int[MAX_SIZE];
    static long[][] transform = new long[20][MAX_SIZE];
    static long[] factorial = new long[MAX_SIZE];
    static long[] inv_factorial = new long[MAX_SIZE];
    static long[][] tmp1_arr = new long[20][MAX_SIZE];
    static long[][] tmp2_arr = new long[20][MAX_SIZE];
    static int[][] tmp3_arr = new int[20][MAX_SIZE];
    static long power_product;

    static long fastExponentiation(long base, int exp) {
        long result = 1;
        long current = base;
        while (exp > 0) {
            if ((exp & 1) == 1) result = result * current % modulus;
            current = current * current % modulus;
            exp >>= 1;
        }
        return result;
    }

    static void initialize() {
        factorial[0] = 1;
        for (int i = 1; i <= max_value; i++)
            factorial[i] = factorial[i - 1] * i % modulus;
        inv_factorial[max_value] = fastExponentiation(factorial[max_value], modulus - 2);
        for (int i = max_value - 1; i >= 0; i--)
            inv_factorial[i] = inv_factorial[i + 1] * (i + 1) % modulus;
    }

    static int get_lower_power(int x) {
        int power = 1;
        while (power < x) power <<= 1;
        return power;
    }

    static void FWT_transform(int[] array, int length, boolean inverse) {
        for (int i = 0; i < length; i++) {
            transform[0][i] = array[i];
        }
        for (int step = 1; step < length; step <<= 1) {
            for (int j = 0; j < length; j += (step << 1)) {
                for (int k = j; k < j + step; k++) {
                    long val = transform[0][k];
                    if (inverse) {
                        transform[0][k + step] -= val;
                    } else {
                        transform[0][k + step] += val;
                    }
                }
            }
        }
        for (int i = 0; i < length; i++) {
            array[i] = (int)(transform[0][i] % modulus);
            if (array[i] < 0) array[i] += modulus;
        }
    }

    static void adjust_mod(long[] x) {
        if (x[0] >= power_product) x[0] -= power_product;
    }

    static void multiply() {
        for (int i = 0; i <= max_value; i++) {
            for (int j = 0; j < 20; j++) {
                tmp1_arr[j][i] = 0;
            }
        }
        for (int j = 0; j < 20; j++) {
            for (int i = 0; i <= max_value; i++) {
                tmp1_arr[j][i] = 0;
            }
        }
        for (int i = 0; i <= max_value; i++) {
            int c = count[i];
            tmp1_arr[c][i] = f_array[i];
        }
        for (int j = 0; j < 20; j++) {
            FWT_transform(tmp1_arr[j], max_value + 1, false);
        }
        for (int q = 0; q <= 19; q++) {
            for (int l = 0; l + q <= 19; l++) {
                for (int s = 0; s <= max_value; s++) {
                    long val = tmp1_arr[q][s] * tmp2_arr[l][s];
                    long[] temp = {transform[q + l][s]};
                    temp[0] += val;
                    adjust_mod(temp);
                    transform[q + l][s] = temp[0];
                }
            }
        }
        for (int q = 0; q <= 19; q++) {
            for (int s = 0; s <= max_value; s++) {
                tmp3_arr[q][s] = (int)(transform[q][s] % modulus);
            }
        }
        for (int j = 0; j < 20; j++) {
            FWT_transform(tmp3_arr[j], max_value + 1, true);
        }
        for (int j = 0; j <= max_value; j++) {
            int c = count[j];
            f_array[j] = tmp3_arr[c][j];
        }
    }

    static void multiply_second() {
        long[][] temp = new long[20][MAX_SIZE];
        for (int i = 0; i <= 19; i++) {
            for (int s = 0; s <= max_value; s++) {
                transform[i][s] = 0;
            }
        }
        for (int q = 0; q <= 19; q++) {
            for (int l = 0; l + q <= 19; l++) {
                for (int s = 0; s <= max_value; s++) {
                    long val = tmp2_arr[q][s] * tmp2_arr[l][s];
                    long[] t = {transform[q + l][s]};
                    t[0] += val;
                    adjust_mod(t);
                    transform[q + l][s] = t[0];
                }
            }
        }
        int[][] tempArr = new int[20][MAX_SIZE];
        for (int i = 0; i <= 19; i++) {
            for (int s = 0; s <= max_value; s++) {
                tempArr[i][s] = (int)(transform[i][s] % modulus);
            }
        }
        for (int i = 0; i <= 19; i++) {
            FWT_transform(tempArr[i], max_value + 1, true);
        }
        for (int i = 0; i <= 19; i++) {
            for (int s = 0; s <= max_value; s++) {
                tmp2_arr[i][s] = 0;
            }
        }
        for (int i = 0; i <= max_value; i++) {
            int c = count[i];
            tmp2_arr[c][i] = tempArr[c][i];
        }
        for (int i = 0; i < 20; i++) {
            FWT_transform(tmp2_arr[i], max_value + 1, false);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        total_numbers = sc.nextInt();
        exponent = sc.nextInt();
        modulus = sc.nextInt();
        power_product = (long) modulus * modulus;
        if ((total_numbers & 1) == 1) {
            System.out.println(fastExponentiation(exponent, total_numbers));
            sc.close();
            return;
        }
        f_array[0] = 1;
        max_value = get_lower_power(total_numbers + 1) - 1;
        initialize();
        for (int i = 0; i <= max_value; i++) {
            count[i] = Integer.bitCount(i);
        }
        for (int i = 0; i <= max_value; i++) {
            int c = count[i];
            tmp2_arr[c][i] = (int)inv_factorial[i];
        }
        for (int i = 0; i < 20; i++) {
            FWT_transform(tmp2_arr[i], max_value + 1, false);
        }
        int res = exponent;
        while (res > 0) {
            if ((res & 1) == 1) {
                multiply();
            }
            res >>= 1;
            if (res > 0) {
                multiply_second();
            }
        }
        long result = (fastExponentiation(exponent, total_numbers) - factorial[total_numbers] * f_array[total_numbers] % modulus + modulus) % modulus;
        System.out.println(result);
        sc.close();
    }
}
